import json,re
def norm(s):
    return s.replace(',','').replace(' ','')
def boxed(s):
    m=re.findall(r'\\boxed\{([^{}]*(?:\{[^{}]*\}[^{}]*)*)\}', s)
    if not m: return None
    t=m[-1]
    # handle \frac{a}{b}
    fm=re.search(r'\\frac\{([^{}]*)\}\{([^{}]*)\}', t)
    if fm:
        try: return float(fm.group(1))/float(fm.group(2))
        except: pass
    n=re.findall(r'-?\d+(?:\.\d+)?', t.replace(',',''))
    return float(n[0]) if n else None
def lastnum(s):
    n=re.findall(r'-?\d+(?:\.\d+)?', s.replace(',',''))
    return float(n[-1]) if n else None
for step in [0,10,20,30,40,50,60]:
    rows=[json.loads(l) for l in open(f'results/run60/val_generations/{step}.jsonl')]
    n=len(rows)
    def acc(f):
        c=0
        for r in rows:
            v=f(r['output']); 
            try:
                if v is not None and abs(v-float(r['gts']))<1e-6: c+=1
            except: pass
        return c/n
